def slots_to_assignments(apps, schema_editor):
    """Every existing ``LineupSelection.slot`` becomes an assignment (a slot was unique per line-up, so nothing collides)."""
    Selection, Assignment = apps.get_model("events", "LineupSelection"), apps.get_model("events", "LineupSlotAssignment")
    Assignment.objects.bulk_create([Assignment(lineup_id=s.lineup_id, member_id=s.member_id, slot=s.slot) for s in Selection.objects.exclude(slot="")])


def assignments_to_slots(apps, schema_editor):
    """Reverse: a selection keeps one slot only (the alphabetically first of its assignments; the others are lost)."""
    Selection, Assignment = apps.get_model("events", "LineupSelection"), apps.get_model("events", "LineupSlotAssignment")
    seen = set()
    for a in Assignment.objects.order_by("slot"):
        if (a.lineup_id, a.member_id) not in seen:
            seen.add((a.lineup_id, a.member_id))
            Selection.objects.filter(lineup_id=a.lineup_id, member_id=a.member_id).update(slot=a.slot)


